<div class="page-head"><div><p class="eyebrow">Mensajería</p><h1>Notificaciones</h1></div>
<form method="post" action="<?= e(url('admin/notificaciones/procesar')) ?>"><?= csrf_field() ?><button class="btn btn-gold btn-sm">Procesar cola ahora</button></form></div>
<div class="tabs"><?php $cn = array_column($counts, 'n', 'status'); foreach (['' => 'Todas', 'pendiente' => 'Pendientes', 'manual' => 'WhatsApp manual', 'enviado' => 'Enviadas', 'error' => 'Con error'] as $k => $l): ?><a class="<?= get('st') === $k ? 'on' : '' ?>" href="<?= e(url('admin/notificaciones?st=' . $k)) ?>"><?= $l ?> <?php if ($k): ?><span class="count mono"><?= (int) ($cn[$k] ?? 0) ?></span><?php endif; ?></a><?php endforeach; ?></div>
<div class="tbl-wrap"><table class="tbl"><tr><th>Fecha</th><th>Canal</th><th>Para</th><th>Mensaje</th><th>Estado</th><th></th></tr>
<?php foreach ($queue as $m): ?><tr><td class="mono" data-l="Fecha"><?= e(fdate($m['created_at'], true)) ?></td><td data-l="Canal"><?= $m['channel'] === 'whatsapp' ? 'WhatsApp' : 'Correo' ?></td><td data-l="Para"><?= e($m['name'] ?: '') ?><br><small class="muted"><?= e($m['to_addr']) ?></small></td>
<td data-l="Mensaje"><strong><?= e($m['subject']) ?></strong><br><small class="muted"><?= e(mb_substr($m['body'], 0, 110)) ?>…</small><?php if ($m['error']): ?><br><small class="err-t"><?= e($m['error']) ?></small><?php endif; ?></td>
<td data-l="Estado"><span class="pill <?= $m['status'] === 'enviado' ? 'p-new' : ($m['status'] === 'error' ? 'p-urgent' : 'p-soon') ?>"><?= e($m['status']) ?></span></td>
<td class="btn-row"><?php if ($m['channel'] === 'whatsapp' && $m['wa_link'] && $m['status'] !== 'enviado'): ?><a class="btn btn-gold btn-sm" href="<?= e($m['wa_link']) ?>" target="_blank" rel="noopener noreferrer">Abrir WhatsApp</a><form method="post" action="<?= e(url('admin/notificaciones/' . $m['id'] . '/enviado')) ?>"><?= csrf_field() ?><button class="btn btn-ghost btn-sm">Marcar enviado</button></form><?php endif; ?>
<?php if ($m['status'] === 'error'): ?><form method="post" action="<?= e(url('admin/notificaciones/' . $m['id'] . '/reintentar')) ?>"><?= csrf_field() ?><button class="btn btn-ghost btn-sm">Reintentar</button></form><?php endif; ?>
<?php if (in_array($m['status'], ['pendiente', 'error', 'manual'])): ?><form method="post" action="<?= e(url('admin/notificaciones/' . $m['id'] . '/descartar')) ?>"><?= csrf_field() ?><button class="btn btn-quiet btn-sm">Descartar</button></form><?php endif; ?></td></tr>
<?php endforeach; if (!$queue) echo '<tr><td colspan="6" class="muted">La cola está vacía.</td></tr>'; ?></table></div>
<section class="card"><h2>Plantillas editables</h2><p class="muted small">Variables: {nombre} {sitio} {enlace} {lista} {cantidad} {panel} {plan} {fecha} {url}</p>
<ul class="similar"><?php foreach ($tpls as $t): ?><li><span><?= e($t['label']) ?></span><a href="<?= e(url('admin/notificaciones?t=' . $t['k'])) ?>#plantilla">Editar</a></li><?php endforeach; ?></ul>
<?php if ($edit): ?><form id="plantilla" method="post" action="<?= e(url('admin/notificaciones/plantilla')) ?>" class="form"><?= csrf_field() ?><input type="hidden" name="k" value="<?= e($edit['k']) ?>"><h3><?= e($edit['label']) ?></h3>
<?php if ($edit['k'] !== 'alert_wa'): ?><?= f_input('subject', 'Asunto', $edit['subject']) ?><?php else: ?><input type="hidden" name="subject" value=""><?php endif; ?>
<?= f_area('body', 'Mensaje', $edit['body'], 9) ?><button class="btn btn-gold">Guardar plantilla</button></form><?php endif; ?></section>
